440 | /* ── Stock row (compact table-style card) ── */
441 | .card {
442 |   display: grid;
443 |   grid-template-columns:
444 |     var(--c-rank) var(--c-spark) var(--c-ticker) var(--c-price)
445 |     var(--c-chg) var(--c-score) var(--c-pe) var(--c-rsi)
446 |     var(--c-eps) var(--c-margin) var(--c-cap);
447 |   align-items: center;
448 |   padding: 0 10px;
449 |   height: 44px;
450 |   background: color-mix(in srgb, hsl(var(--card-hue, 220) 60% 18%) 22%, var(--bg2));
451 |   border: 1px solid hsl(var(--card-hue, 220) 55% 38%);
452 |   border-left: 3px solid hsl(var(--card-hue, 220) 80% 58%);
453 |   border-radius: var(--radius);
454 |   cursor: pointer;
455 |   transition: background .18s, border-color .18s, transform .18s cubic-bezier(0.34,1.56,0.64,1), box-shadow .18s;
456 |   will-change: transform;
457 | }
458 | .card:hover {
459 |   background: color-mix(in srgb, hsl(var(--card-hue, 220) 70% 28%) 35%, var(--bg3));
460 |   border-color: hsl(var(--card-hue, 220) 90% 68%);
461 |   border-left-color: hsl(var(--card-hue, 220) 90% 72%);
462 |   transform: translateX(4px) scale(1.012);
463 |   box-shadow: -3px 0 0 0 hsl(var(--card-hue, 220) 80% 58%), 0 6px 24px hsl(var(--card-hue, 220) 70% 50% / .2);
464 |   z-index: 1;
465 |   position: relative;
466 | }
467 | 
468 | body.light .card {
469 |   background: color-mix(in srgb, hsl(var(--card-hue, 220) 80% 60%) 10%, var(--bg2));
470 |   border-color: hsl(var(--card-hue, 220) 55% 68%);
471 |   border-left-color: hsl(var(--card-hue, 220) 70% 50%);
472 | }
473 | body.light .card:hover {
474 |   background: color-mix(in srgb, hsl(var(--card-hue, 220) 80% 60%) 18%, var(--bg3));
475 |   border-color: hsl(var(--card-hue, 220) 70% 45%);
476 |   box-shadow: -3px 0 0 0 hsl(var(--card-hue, 220) 70% 50%), 0 6px 24px hsl(var(--card-hue, 220) 60% 50% / .18);
477 | }
478 | 
479 | /* rank */
480 | .row-rank { text-align: center; font-size: .75rem; color: var(--muted); font-weight: 600; transition: transform .2s cubic-bezier(0.34,1.56,0.64,1); }
481 | .row-rank.top3 { color: var(--gold); font-weight: 700; }
482 | .card:hover .row-rank { transform: scale(1.35); }
483 | 
484 | /* sparkline cell */
485 | .row-spark { width: var(--c-spark); height: 36px; display: flex; align-items: center; padding: 0 4px; transition: filter .2s, transform .2s; }
486 | .row-spark canvas { display: block; width: 100%; height: 36px; transition: filter .2s; }
487 | .card:hover .row-spark { transform: scaleY(1.12); }
488 | .card:hover .row-spark canvas { filter: brightness(1.35) drop-shadow(0 0 4px hsl(var(--card-hue, 220) 80% 58% / .6)); }
489 | 
490 | /* ticker + name stacked */
491 | .row-ticker { display: flex; flex-direction: column; gap: 1px; overflow: hidden; padding-right: 6px; }
