 350 | // ── Sparkline (pure canvas, compact 36 px tall) ───────────────────────────
 351 | function drawSparkline(s) {
 352 |   const canvas = document.getElementById(`spark-${s.ticker}`);
 353 |   if (!canvas || !s.sparkline || s.sparkline.length < 2) return;
 354 | 
 355 |   const dpr = window.devicePixelRatio || 1;
 356 |   const w   = canvas.parentElement.clientWidth - 8; // subtract padding
 357 |   const h   = 36;
 358 |   canvas.width  = w * dpr;
 359 |   canvas.height = h * dpr;
 360 |   canvas.style.width  = w + 'px';
 361 |   canvas.style.height = h + 'px';
 362 |   const ctx = canvas.getContext('2d');
 363 |   ctx.scale(dpr, dpr);
 364 | 
 365 |   const prices = s.sparkline;
 366 |   const min    = Math.min(...prices);
 367 |   const max    = Math.max(...prices);
 368 |   const range  = max - min || 1;
 369 |   const pad    = 2;
 370 |   const xFn    = i => (i / (prices.length - 1)) * (w - pad * 2) + pad;
 371 |   const yFn    = v => h - pad - ((v - min) / range) * (h - pad * 2);
 372 | 
 373 |   const isUp = prices[prices.length - 1] >= prices[0];
 374 |   const col  = isUp ? '63,185,80' : '248,81,73';
 375 |   const grad = ctx.createLinearGradient(0, 0, 0, h);
 376 |   grad.addColorStop(0, `rgba(${col},.25)`);
 377 |   grad.addColorStop(1, `rgba(${col},0)`);
 378 | 
 379 |   // filled area
 380 |   ctx.beginPath();
 381 |   ctx.moveTo(xFn(0), yFn(prices[0]));
 382 |   prices.forEach((p, i) => { if (i > 0) ctx.lineTo(xFn(i), yFn(p)); });
 383 |   ctx.lineTo(xFn(prices.length - 1), h);
 384 |   ctx.lineTo(xFn(0), h);
 385 |   ctx.closePath();
 386 |   ctx.fillStyle = grad;
 387 |   ctx.fill();
 388 | 
 389 |   // line
 390 |   ctx.beginPath();
 391 |   ctx.moveTo(xFn(0), yFn(prices[0]));
 392 |   prices.forEach((p, i) => { if (i > 0) ctx.lineTo(xFn(i), yFn(p)); });
 393 |   ctx.strokeStyle = `rgb(${col})`;
 394 |   ctx.lineWidth   = 1.5;
 395 |   ctx.lineJoin    = 'round';
 396 |   ctx.stroke();
 397 | }
