1074 | function rejectClick(card, ticker) {
1075 |   // Don't pile on rejections if already shaking
1076 |   if (card.classList.contains('card-rejected')) return;
1077 | 
1078 |   // Flash the card red + shake
1079 |   card.classList.add('card-rejected');
1080 |   card.addEventListener('animationend', () => {
1081 |     card.classList.remove('card-rejected');
1082 |   }, { once: true });
