1089 | let _denialTimer = null;
1090 | function showDenialOverlay(ticker, msg) {
1091 |   // Kill any existing denial elements so it always feels fresh
1092 |   ['denial-vignette','denial-overlay','denial-msg-bar'].forEach(id => {
1093 |     const el = document.getElementById(id);
1094 |     if (el) el.remove();
1095 |   });
1096 |   clearTimeout(_denialTimer);
1097 | 
1098 |   const ANIM_MS = 1000;
1099 | 
1100 |   // 1 ── Red vignette border flash
1101 |   const vignette = document.createElement('div');
1102 |   vignette.id        = 'denial-vignette';
1103 |   vignette.className = 'denial-vignette';
1104 |   document.body.appendChild(vignette);
1105 | 
1106 |   // 2 ── Dark overlay with the stamp
1107 |   const overlay = document.createElement('div');
1108 |   overlay.id        = 'denial-overlay';
1109 |   overlay.className = 'denial-overlay';
1110 |   overlay.innerHTML = `
1111 |     <div class="denial-stamp">
1112 |       <div class="denial-stamp-icon">⛔</div>
1113 |       <div class="denial-stamp-text">DENIED</div>
1114 |       <div class="denial-stamp-sub">${ticker}</div>
1115 |     </div>`;
1116 |   document.body.appendChild(overlay);
1117 | 
1118 |   // 3 ── Snarky message bar slides up from bottom
1119 |   const msgBar = document.createElement('div');
1120 |   msgBar.id        = 'denial-msg-bar';
1121 |   msgBar.className = 'denial-msg-bar';
1122 |   msgBar.textContent = msg;
1123 |   document.body.appendChild(msgBar);
1124 | 
1125 |   // 4 ── Laugh track 😂
1126 |   playLaughTrack();
1127 | 
1128 |   // Clean up all three after animation completes
1129 |   _denialTimer = setTimeout(() => {
1130 |     [vignette, overlay, msgBar].forEach(el => el.remove());
1131 |   }, ANIM_MS + 80);
1132 | }
1133 | 
1134 | // ── Synthesised laugh track via Web Audio API ─────────────────────────────
1135 | function playLaughTrack() {
1136 |   let ctx;
1137 |   try {
1138 |     ctx = new (window.AudioContext || window.webkitAudioContext)();
1139 |   } catch (_) { return; } // browser doesn't support Web Audio — silently skip
1140 | 
1141 |   // Master gain so we can fade the whole laugh out at the end
1142 |   const master = ctx.createGain();
1143 |   master.gain.setValueAtTime(0.55, ctx.currentTime);
1144 |   master.gain.linearRampToValueAtTime(0, ctx.currentTime + 2.4);
1145 |   master.connect(ctx.destination);
1146 | 
1147 |   // Each "laugh voice" is a short burst of descending tones
1148 |   // We layer several voices with different timings & pitches for a crowd feel
1149 |   const voices = [
1150 |     { baseFreq: 420, offset: 0.00, count: 5, speed: 0.13, vol: 0.55 },
1151 |     { baseFreq: 370, offset: 0.05, count: 6, speed: 0.12, vol: 0.45 },
1152 |     { baseFreq: 500, offset: 0.02, count: 4, speed: 0.15, vol: 0.35 },
1153 |     { baseFreq: 340, offset: 0.08, count: 5, speed: 0.11, vol: 0.40 },
1154 |     { baseFreq: 460, offset: 0.03, count: 6, speed: 0.14, vol: 0.30 },
1155 |     { baseFreq: 390, offset: 0.11, count: 4, speed: 0.13, vol: 0.38 },
1156 |   ];
1157 | 
1158 |   voices.forEach(({ baseFreq, offset, count, speed, vol }) => {
1159 |     for (let i = 0; i < count; i++) {
1160 |       const t = ctx.currentTime + offset + i * speed;
1161 | 
1162 |       // Each "ha" = a quick pitch-bend from high → low (the "ha" shape)
1163 |       const osc  = ctx.createOscillator();
1164 |       const gain = ctx.createGain();
1165 | 
1166 |       osc.type = 'sine';
1167 |       // Slight random variation so voices don't sound identical
1168 |       const freq = baseFreq * (1 + (Math.random() - 0.5) * 0.12);
1169 |       osc.frequency.setValueAtTime(freq * 1.18, t);
1170 |       osc.frequency.exponentialRampToValueAtTime(freq * 0.72, t + 0.09);
1171 | 
1172 |       // Attack → short sustain → decay envelope
1173 |       gain.gain.setValueAtTime(0, t);
1174 |       gain.gain.linearRampToValueAtTime(vol, t + 0.018);
1175 |       gain.gain.setValueAtTime(vol,       t + 0.055);
1176 |       gain.gain.exponentialRampToValueAtTime(0.001, t + 0.115);
1177 | 
1178 |       osc.connect(gain);
1179 |       gain.connect(master);
1180 |       osc.start(t);
1181 |       osc.stop(t + 0.13);
1182 | 
1183 |       // Add a subtle overtone (2nd harmonic) for a more "vocal" texture
1184 |       const osc2  = ctx.createOscillator();
1185 |       const gain2 = ctx.createGain();
1186 |       osc2.type = 'triangle';
1187 |       osc2.frequency.setValueAtTime(freq * 2.2, t);
1188 |       osc2.frequency.exponentialRampToValueAtTime(freq * 1.4, t + 0.09);
1189 |       gain2.gain.setValueAtTime(0, t);
1190 |       gain2.gain.linearRampToValueAtTime(vol * 0.22, t + 0.018);
1191 |       gain2.gain.exponentialRampToValueAtTime(0.001, t + 0.10);
1192 |       osc2.connect(gain2);
1193 |       gain2.connect(master);
1194 |       osc2.start(t);
1195 |       osc2.stop(t + 0.12);
1196 |     }
1197 |   });
1198 | 
1199 |   // Auto-close the AudioContext after the laugh finishes
1200 |   setTimeout(() => { try { ctx.close(); } catch (_) {} }, 2600);
1201 | }
1202 | 
