1218 | // ══════════════════════════════════════════════════════════════════════════════
1219 | // LIVE FEED — Continuously pumps fresh top picks into the card grid
1220 | // ══════════════════════════════════════════════════════════════════════════════
1221 | 
1222 | const FEED_INTERVAL_MS = 9000;
1223 | const FEED_SECTORS     = ['all', 'Technology', 'Healthcare', 'Financials', 'Consumer', 'Energy', 'Industrials'];
1224 | const FEED_MODES       = ['random', 'balanced', 'momentum', 'value', 'quality', 'technical'];
