1256 | function stopLiveFeed() {
1257 |   _feedRunning = false;
1258 |   clearTimeout(_feedTimerId);
1259 |   cancelAnimationFrame(_feedProgressTimer);
1260 |   const btn   = document.getElementById('live-toggle');
1261 |   const badge = document.getElementById('live-badge');
