1271 | async function _runFeedCycle() {
1272 |   if (!_feedRunning) return;
1273 |   const sector = FEED_SECTORS[Math.floor(Math.random() * FEED_SECTORS.length)];
1274 |   const mode   = FEED_MODES[Math.floor(Math.random() * FEED_MODES.length)];
1275 | 
1276 |   try {
1277 |     const res  = await fetch(`${API}/top-stocks?sector=${encodeURIComponent(sector)}&mode=${mode}`);
1278 |     if (!res.ok) throw new Error('fetch failed');
1279 |     const data = await res.json();
1280 |     const incoming = data.stocks || [];
1281 | 
1282 |     if (incoming.length > 0) {
1283 |       const grid         = document.getElementById('cards-grid');
1284 |       const shownTickers = new Set([...grid.querySelectorAll('.card')].map(c => c.dataset.ticker));
1285 | 
1286 |       const candidate = incoming
1287 |         .sort((a, b) => b.score - a.score)
1288 |         .find(s => !shownTickers.has(s.ticker)) || incoming[0];
1289 | 
1290 |       if (!_feedStockPool.find(s => s.ticker === candidate.ticker)) {
1291 |         _feedStockPool.push(candidate);
1292 |         stockData = _feedStockPool;
1293 |         persistScoreHistory([candidate]);
1294 |       }
1295 | 
1296 |       const card = buildCard(candidate, 1);
1297 |       card.classList.add('card-drop', 'card-glow');
1298 | 
1299 |       if (grid.firstChild) grid.insertBefore(card, grid.firstChild);
1300 |       else grid.appendChild(card);
1301 | 
1302 |       _renumberFeedCards(grid);
1303 |       requestAnimationFrame(() => drawSparkline(candidate));
1304 |       _trimFeedGrid(grid);
1305 | 
1306 |       document.getElementById('last-updated').textContent =
1307 |         'Live · ' + new Date().toLocaleTimeString();
1308 |     }
1309 |   } catch (_) { /* silent — feed keeps going */ }
1310 | 
1311 |   if (_feedRunning) {
1312 |     _feedCycleStart = performance.now();
1313 |     _animateFeedProgress();
1314 |     _feedTimerId = setTimeout(_runFeedCycle, FEED_INTERVAL_MS);
1315 |   }
1316 | }
1317 | 
1318 | function _animateFeedProgress() {
1319 |   const fill = document.getElementById('feed-progress-fill');
1320 |   if (!fill || !_feedRunning) return;
1321 |   const pct = Math.min(((performance.now() - _feedCycleStart) / FEED_INTERVAL_MS) * 100, 100);
1322 |   fill.style.width = pct + '%';
1323 |   if (pct < 100 && _feedRunning) {
1324 |     _feedProgressTimer = requestAnimationFrame(_animateFeedProgress);
1325 |   } else {
1326 |     fill.style.transition = 'none';
1327 |     fill.style.width = '0%';
1328 |     requestAnimationFrame(() => { fill.style.transition = 'width 0.25s linear'; });
1329 |   }
1330 | }
1331 | 
1332 | function _renumberFeedCards(grid) {
1333 |   const medals = ['🥇','🥈','🥉'];
1334 |   [...grid.querySelectorAll('.card')].forEach((card, i) => {
1335 |     const rankEl = card.querySelector('.row-rank');
