1339 |       rankEl.textContent = medals[rank - 1];
1340 |       rankEl.classList.add('top3');
1341 |     } else {
1342 |       rankEl.textContent = `#${rank}`;
1343 |       rankEl.classList.remove('top3');
1344 |     }
1345 |   });
1346 | }
1347 | 
1348 | function _trimFeedGrid(grid) {
1349 |   const cards = [...grid.querySelectorAll('.card')];
1350 |   if (cards.length <= FEED_MAX_CARDS) return;
1351 |   cards.slice(FEED_MAX_CARDS).forEach(card => {
1352 |     card.style.transition = 'opacity 0.4s ease, transform 0.4s ease';
1353 |     card.style.opacity    = '0';
1354 |     card.style.transform  = 'translateX(20px)';
1355 |     setTimeout(() => card.remove(), 420);
1356 |   });
1357 | }

