/* ── Trigger button ── */
.btn-minigame {
  background: linear-gradient(135deg, #a371f7 0%, #58a6ff 100%);
  color: #fff;
  position: relative;
  overflow: hidden;
}
.btn-minigame::after {
  content: '';
  position: absolute;
  inset: 0;
  background: rgba(255,255,255,0);
  transition: background .15s;
}
.btn-minigame:hover::after { background: rgba(255,255,255,.12); }

/* ── Full-screen game overlay ── */
#mg-overlay {
  position: fixed;
  inset: 0;
  z-index: 9000;
  background: rgba(0,0,0,.82);
  backdrop-filter: blur(6px);
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  pointer-events: none;
  transition: opacity .25s;
}
#mg-overlay.open {
  opacity: 1;
  pointer-events: all;
}

/* ── Game card shell ── */
.mg-card {
  background: var(--bg2);
  border: 1px solid var(--border);
  border-radius: 16px;
  box-shadow: 0 24px 80px rgba(0,0,0,.7);
  width: min(520px, 96vw);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  position: relative;
}

/* ── Top header bar ── */
.mg-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 20px 12px;
  border-bottom: 1px solid var(--border);
  background: var(--bg3);
}
.mg-title {
  font-size: 1rem;
  font-weight: 800;
  display: flex;
  align-items: center;
  gap: 8px;
}
.mg-title-icon { font-size: 1.2rem; }
.mg-meta {
  display: flex;
  align-items: center;
  gap: 14px;
  font-size: .78rem;
  color: var(--muted);
}
.mg-meta-val {
  font-weight: 700;
  color: var(--text);
}
.mg-close {
  background: none;
  border: none;
  color: var(--muted);
  font-size: 1.1rem;
  cursor: pointer;
  padding: 2px 6px;
  border-radius: 4px;
  transition: background .15s, color .15s;
  line-height: 1;
}
.mg-close:hover { background: var(--bg); color: var(--text); }

/* ── Timer bar ── */
.mg-timer-track {
  height: 4px;
  background: var(--bg3);
  width: 100%;
}
.mg-timer-fill {
  height: 100%;
  background: var(--accent);
  width: 100%;
  transform-origin: left;
  transition: width linear;
}
.mg-timer-fill.urgent { background: var(--red); }

/* ── Body ── */
.mg-body {
  padding: 20px 24px 16px;
}

/* ── Stock hero row ── */
.mg-stock-hero {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 16px;
}
.mg-stock-left { flex: 1; min-width: 0; }
.mg-ticker {
  font-size: 2rem;
  font-weight: 900;
  color: var(--accent);
  line-height: 1;
  letter-spacing: -.02em;
}
.mg-name {
  font-size: .8rem;
  color: var(--muted);
  margin-top: 3px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  max-width: 220px;
}
.mg-sector-chip {
  display: inline-block;
  background: rgba(88,166,255,.12);
  color: var(--accent);
  border: 1px solid rgba(88,166,255,.2);
  border-radius: 20px;
  font-size: .65rem;
  font-weight: 700;
  padding: 2px 9px;
  margin-top: 5px;
  letter-spacing: .03em;
}
.mg-price-block { text-align: right; flex-shrink: 0; }
.mg-price {
  font-size: 1.6rem;
  font-weight: 800;
  line-height: 1;
}
.mg-day-change {
  font-size: .82rem;
  font-weight: 600;
  margin-top: 3px;
}
.mg-day-change.up   { color: var(--green); }
.mg-day-change.down { color: var(--red); }
.mg-day-change.flat { color: var(--muted); }

/* ── Sparkline canvas ── */
.mg-spark-wrap {
  width: 100%;
  height: 80px;
  margin-bottom: 14px;
  position: relative;
}
#mg-spark {
  width: 100%;
  height: 100%;
  display: block;
}
.mg-spark-label {
  position: absolute;
  right: 0;
  top: 0;
  font-size: .62rem;
  color: var(--muted);
  background: var(--bg2);
  padding: 1px 5px;
  border-radius: 4px;
}

/* ── Stats row ── */
.mg-stats {
  display: flex;
  gap: 10px;
  margin-bottom: 18px;
  flex-wrap: wrap;
}
.mg-stat {
  background: var(--bg3);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 7px 12px;
  flex: 1;
  min-width: 70px;
  text-align: center;
}
.mg-stat-label {
  font-size: .6rem;
  text-transform: uppercase;
  letter-spacing: .06em;
  color: var(--muted);
  margin-bottom: 3px;
}
.mg-stat-val {
  font-size: .9rem;
  font-weight: 700;
  color: var(--text);
}
.mg-stat-val.up     { color: var(--green); }
.mg-stat-val.down   { color: var(--red); }
.mg-stat-val.warn   { color: var(--gold); }

/* ── CTA hint ── */
.mg-cta {
  text-align: center;
  font-size: .75rem;
  color: var(--muted);
  margin-bottom: 14px;
  font-style: italic;
}

/* ── Action buttons ── */
.mg-actions {
  display: flex;
  gap: 12px;
  padding: 0 24px 20px;
}
.mg-btn {
  flex: 1;
  height: 52px;
  border: none;
  border-radius: 10px;
  font-size: 1rem;
  font-weight: 800;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  letter-spacing: .01em;
  transition: transform .15s cubic-bezier(0.34,1.56,0.64,1),
              box-shadow .15s,
              opacity .15s;
  position: relative;
  overflow: hidden;
}
.mg-btn:hover  { transform: translateY(-3px) scale(1.03); }
.mg-btn:active { transform: scale(.96); }
.mg-btn:disabled { opacity: .35; cursor: default; transform: none; }

.mg-btn-bull {
  background: linear-gradient(135deg, #1a7f37, #3fb950);
  color: #fff;
  box-shadow: 0 4px 20px rgba(63,185,80,.3);
}
.mg-btn-bull:hover { box-shadow: 0 6px 28px rgba(63,185,80,.45); }

.mg-btn-bear {
  background: linear-gradient(135deg, #b91c1c, #f85149);
  color: #fff;
  box-shadow: 0 4px 20px rgba(248,81,73,.3);
}
.mg-btn-bear:hover { box-shadow: 0 6px 28px rgba(248,81,73,.45); }

.mg-btn-icon { font-size: 1.3rem; }

/* ── Result overlay (shown inside card after guess) ── */
.mg-result {
  position: absolute;
  inset: 0;
  border-radius: 16px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;
  opacity: 0;
  pointer-events: none;
  transition: opacity .2s;
  z-index: 10;
}
.mg-result.visible {
  opacity: 1;
  pointer-events: all;
}
.mg-result.correct { background: rgba(31,101,55,.9); }
.mg-result.wrong   { background: rgba(108,23,23,.9); }
.mg-result.timeout { background: rgba(40,40,50,.92); }

.mg-result-icon { font-size: 3.5rem; animation: mg-pop .35s cubic-bezier(0.34,1.56,0.64,1); }
.mg-result-title { font-size: 1.6rem; font-weight: 900; color: #fff; }
.mg-result-subtitle { font-size: .85rem; color: rgba(255,255,255,.75); text-align: center; padding: 0 24px; }
.mg-result-pts {
  font-size: 1.1rem;
  font-weight: 800;
  padding: 5px 18px;
  border-radius: 20px;
  background: rgba(255,255,255,.15);
  color: #fff;
}
.mg-result-next {
  margin-top: 4px;
  font-size: .72rem;
  color: rgba(255,255,255,.55);
}

/* ── Streak badge ── */
.mg-streak-badge {
  position: absolute;
  top: 60px;
  right: 20px;
  background: var(--gold);
  color: #0d1117;
  border-radius: 20px;
  font-size: .7rem;
  font-weight: 800;
  padding: 3px 10px;
  display: none;
  animation: mg-pop .3s cubic-bezier(0.34,1.56,0.64,1);
}
.mg-streak-badge.show { display: block; }

/* ── Loading / error state ── */
.mg-loading {
  padding: 48px 24px;
  text-align: center;
  color: var(--muted);
  font-size: .9rem;
}
.mg-loading .spinner {
  width: 28px; height: 28px;
  border: 3px solid var(--border);
  border-top-color: var(--accent);
  border-radius: 50%;
  animation: spin .7s linear infinite;
  margin: 0 auto 12px;
}

/* ── Game over screen ── */
.mg-gameover {
  padding: 28px 24px 24px;
  text-align: center;
}
.mg-gameover-emoji { font-size: 3rem; margin-bottom: 8px; }
.mg-gameover-title { font-size: 1.4rem; font-weight: 900; margin-bottom: 4px; }
.mg-gameover-subtitle { font-size: .82rem; color: var(--muted); margin-bottom: 20px; }

.mg-score-display {
  display: flex;
  justify-content: center;
  gap: 24px;
  margin-bottom: 20px;
  flex-wrap: wrap;
}
.mg-score-block {
  background: var(--bg3);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 12px 20px;
  min-width: 90px;
}
.mg-score-block-label {
  font-size: .62rem;
  text-transform: uppercase;
  letter-spacing: .06em;
  color: var(--muted);
  margin-bottom: 4px;
}
.mg-score-block-val {
  font-size: 1.6rem;
  font-weight: 900;
  color: var(--accent);
}
.mg-score-block-val.gold  { color: var(--gold); }
.mg-score-block-val.green { color: var(--green); }

.mg-scoreboard {
  width: 100%;
  max-height: 200px;
  overflow-y: auto;
  margin-bottom: 18px;
}
.mg-scoreboard table {
  width: 100%;
  border-collapse: collapse;
  font-size: .78rem;
}
.mg-scoreboard th {
  text-align: left;
  color: var(--muted);
  font-weight: 600;
  padding: 4px 8px;
  border-bottom: 1px solid var(--border);
  font-size: .66rem;
  text-transform: uppercase;
  letter-spacing: .05em;
}
.mg-scoreboard td {
  padding: 5px 8px;
  border-bottom: 1px solid rgba(48,54,61,.5);
}
.mg-scoreboard tr.correct td { color: var(--green); }
.mg-scoreboard tr.wrong td   { color: var(--red); }
.mg-scoreboard tr.timeout td { color: var(--muted); }
.mg-scoreboard .ticker-cell  { font-weight: 700; }
.mg-scoreboard .pts-cell     { font-weight: 700; text-align: right; }

.mg-gameover-actions {
  display: flex;
  gap: 10px;
  justify-content: center;
}
.mg-btn-play-again {
  background: linear-gradient(135deg, #a371f7, #58a6ff);
  color: #fff;
  border: none;
  border-radius: 8px;
  padding: 9px 24px;
  font-size: .88rem;
  font-weight: 700;
  cursor: pointer;
  transition: transform .15s cubic-bezier(0.34,1.56,0.64,1), box-shadow .15s;
}
.mg-btn-play-again:hover { transform: translateY(-2px) scale(1.04); box-shadow: 0 6px 20px rgba(163,113,247,.35); }

.mg-btn-close-gameover {
  background: var(--bg3);
  color: var(--text);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 9px 18px;
  font-size: .88rem;
  font-weight: 600;
  cursor: pointer;
  transition: border-color .15s, transform .15s;
}
.mg-btn-close-gameover:hover { border-color: var(--accent); transform: translateY(-1px); }

.mg-highscore-badge {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  background: rgba(210,153,34,.15);
  color: var(--gold);
  border: 1px solid rgba(210,153,34,.25);
  border-radius: 20px;
  font-size: .72rem;
  font-weight: 700;
  padding: 3px 12px;
  margin-bottom: 16px;
  animation: mg-pop .4s cubic-bezier(0.34,1.56,0.64,1);
}

/* ── Keyboard hint ── */
.mg-keyboard-hint {
  text-align: center;
  font-size: .64rem;
  color: var(--muted);
  padding: 0 24px 10px;
  opacity: .7;
}
.mg-key {
  display: inline-block;
  background: var(--bg3);
  border: 1px solid var(--border);
  border-radius: 4px;
  padding: 1px 6px;
  font-family: monospace;
  font-size: .68rem;
  color: var(--text);
  margin: 0 1px;
}

/* ── How-to-play blurb ── */
.mg-howto {
  margin: 0 24px 12px;
  background: var(--bg3);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 8px 12px;
  font-size: .72rem;
  color: var(--muted);
  line-height: 1.55;
}
.mg-howto strong { color: var(--text); }

/* ── Animations ── */
@keyframes mg-pop {
  from { transform: scale(.5); opacity: 0; }
  to   { transform: scale(1);  opacity: 1; }
}

@keyframes mg-timer-pulse {
  0%, 100% { opacity: 1; }
  50%       { opacity: .5; }
}

@keyframes mg-shake {
  0%,100% { transform: translateX(0); }
  20%      { transform: translateX(-8px); }
  40%      { transform: translateX(8px); }
  60%      { transform: translateX(-5px); }
  80%      { transform: translateX(5px); }
}

.mg-card.shake { animation: mg-shake .35s ease; }

/* ── Round progress dots ── */
.mg-round-dots {
  display: flex;
  gap: 5px;
  justify-content: center;
  padding: 8px 0 0;
}
.mg-dot {
  width: 8px; height: 8px;
  border-radius: 50%;
  background: var(--border);
  transition: background .2s, transform .2s;
}
.mg-dot.done-correct { background: var(--green); }
.mg-dot.done-wrong   { background: var(--red); }
.mg-dot.done-timeout { background: var(--muted); }
.mg-dot.current      { background: var(--accent); transform: scale(1.3); }

/* ── Multiplier flash ── */
.mg-multiplier-flash {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%) scale(.5);
  font-size: 2.5rem;
  font-weight: 900;
  color: var(--gold);
  pointer-events: none;
  opacity: 0;
  text-shadow: 0 0 20px rgba(210,153,34,.6);
  z-index: 20;
}
.mg-multiplier-flash.animate {
  animation: mg-multi-pop .6s cubic-bezier(0.34,1.56,0.64,1) forwards;
}
@keyframes mg-multi-pop {
  0%   { opacity: 0; transform: translate(-50%, -50%) scale(.5); }
  40%  { opacity: 1; transform: translate(-50%, -50%) scale(1.2); }
  70%  { opacity: 1; transform: translate(-50%, -50%) scale(1); }
  100% { opacity: 0; transform: translate(-50%, -70%) scale(0.8); }
}

