/* ── Bull or Bear? Minigame ──────────────────────────────────────────────── */
/* Standalone module — no global namespace pollution beyond openMinigame()    */

(function () {
  'use strict';

  // ── Constants ─────────────────────────────────────────────────────────────
  const API           = 'http://127.0.0.1:5000/api';
  const TOTAL_ROUNDS  = 10;
  const TIMER_SECS    = 9;          // seconds per round
  const BASE_POINTS   = 100;        // correct answer base pts
  const SPEED_BONUS   = 30;         // extra pts for fast answers (<3s)
  const LS_HIGHSCORE  = 'mg_highscore';
  const SECTORS       = ['all', 'Technology', 'Healthcare', 'Financials',
                         'Consumer', 'Energy', 'Industrials'];

  // ── State ─────────────────────────────────────────────────────────────────
  let pool       = [];   // shuffled stock pool for this session
  let roundIdx   = 0;
  let score      = 0;
  let streak     = 0;
  let history    = [];   // { ticker, guess, actual, pts, outcome }
  let timerID    = null;
  let timerStart = 0;
  let timerFill  = null;
  let timerRAF   = null;
  let guessed    = false;

  // ── DOM refs (populated on first open) ───────────────────────────────────
  let overlay, card, resultEl, streakBadge, multFlash, timerFillEl;

  // ── Entry point ───────────────────────────────────────────────────────────
  window.openMinigame = async function () {
    _ensureDOM();
    overlay.classList.add('open');
    document.addEventListener('keydown', _onKey);
    await _startGame();
  };

  function _closeGame() {
    overlay.classList.remove('open');
    document.removeEventListener('keydown', _onKey);
    _stopTimer();
  }

  // ── Keyboard handler ─────────────────────────────────────────────────────
  function _onKey(e) {
    if (!overlay.classList.contains('open')) return;
    if (e.key === 'Escape') { _closeGame(); return; }

    // During active round
    if (!guessed) {
      if (e.key === 'ArrowUp'   || e.key === 'u' || e.key === 'U') _guess('up');
      if (e.key === 'ArrowDown' || e.key === 'd' || e.key === 'D') _guess('down');
    } else {
      // Spacebar / Enter advances
      if (e.key === ' ' || e.key === 'Enter') _nextRound();
    }
  }

  // ── Game lifecycle ────────────────────────────────────────────────────────
  async function _startGame() {
    pool    = [];
    roundIdx = 0;
    score   = 0;
    streak  = 0;
    history = [];
    _showLoading('Fetching stocks…');
    try {
      pool = await _fetchPool();
    } catch (err) {
      _showLoading(`⚠️ Could not load stocks: ${err.message}`);
      return;
    }
    if (pool.length < TOTAL_ROUNDS) {
      _showLoading(`⚠️ Not enough stocks fetched (got ${pool.length}).`);
      return;
    }
    _showRound();
  }

  async function _fetchPool() {
    // Fetch from two different sectors to get variety
    const sectorA = SECTORS[Math.floor(Math.random() * SECTORS.length)];
    const sectorB = SECTORS[Math.floor(Math.random() * SECTORS.length)];
    const [a, b] = await Promise.all([
      fetch(`${API}/top-stocks?sector=${encodeURIComponent(sectorA)}&mode=random`).then(r => r.json()),
      fetch(`${API}/top-stocks?sector=${encodeURIComponent(sectorB)}&mode=momentum`).then(r => r.json()),
    ]);
    const combined = [...(a.stocks || []), ...(b.stocks || [])];
    // Deduplicate by ticker
    const seen = new Set();
    const unique = combined.filter(s => {
      if (seen.has(s.ticker)) return false;
      seen.add(s.ticker);
      return true;
    });
    // Fisher-Yates shuffle
    for (let i = unique.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [unique[i], unique[j]] = [unique[j], unique[i]];
    }
    return unique;
  }

  function _showRound() {
    guessed = false;
    const stock = pool[roundIdx];
    _renderRound(stock);
    _startTimer(stock);
  }

  // ── Render a round ────────────────────────────────────────────────────────
  function _renderRound(s) {
    const change = s.change1d ?? 0;
    const chgCls = change > 0 ? 'up' : change < 0 ? 'down' : 'flat';
    const chgStr = change > 0 ? `+${change.toFixed(2)}%` : `${change.toFixed(2)}%`;

    const rsi    = s.rsi ?? null;
    const pe     = s.pe  ?? null;
    const score_ = s.score ?? null;
    const aiCls  = score_ >= 65 ? 'up' : score_ >= 40 ? '' : 'down';
    const rsiCls = rsi   > 70  ? 'down' : rsi < 35 ? 'up' : 'warn';

    const mult = _multiplier();

    card.innerHTML = `
      <div class="mg-header">
        <div class="mg-title"><span class="mg-title-icon">🐂🐻</span> Bull or Bear?</div>
        <div class="mg-meta">
          <span>Round <span class="mg-meta-val">${roundIdx + 1}/${TOTAL_ROUNDS}</span></span>
          <span>Score <span class="mg-meta-val">${score}</span></span>
          ${mult > 1 ? `<span style="color:var(--gold);font-weight:800;">${mult}× STREAK</span>` : ''}
        </div>
        <button class="mg-close" onclick="(function(){document.getElementById('mg-overlay').classList.remove('open');document.removeEventListener('keydown',window._mgKey);})()">✕</button>
      </div>

      <div class="mg-timer-track">
        <div class="mg-timer-fill" id="mg-timer-fill"></div>
      </div>

      <div class="mg-body">
        <div class="mg-stock-hero">
          <div class="mg-stock-left">
            <div class="mg-ticker">${s.ticker}</div>
            <div class="mg-name">${s.name || ''}</div>
            <div class="mg-sector-chip">${s.sector || 'Market'}</div>
          </div>
          <div class="mg-price-block">
            <div class="mg-price">$${_fmt(s.price)}</div>
            <div class="mg-day-change ${chgCls}">${chgStr} today</div>
          </div>
        </div>

        <div class="mg-spark-wrap">
          <canvas id="mg-spark"></canvas>
          <span class="mg-spark-label">30-day</span>
        </div>

        <div class="mg-stats">
          ${_statHTML('AI Score', score_ !== null ? score_.toFixed(0) : '—', aiCls)}
          ${_statHTML('RSI', rsi !== null ? rsi.toFixed(0) : '—', rsiCls)}
          ${_statHTML('P/E', pe !== null ? pe.toFixed(1) : '—', pe > 50 ? 'down' : pe < 15 ? 'up' : '')}
          ${_statHTML('52w Lo/Hi', _52wStr(s), '')}
        </div>

        <div class="mg-cta">Will this stock be <strong>higher or lower</strong> next week?</div>
      </div>

      <div class="mg-actions">
        <button class="mg-btn mg-btn-bull" id="mg-bull-btn" onclick="window._mgGuess('up')">
          <span class="mg-btn-icon">📈</span> BULL — UP
        </button>
        <button class="mg-btn mg-btn-bear" id="mg-bear-btn" onclick="window._mgGuess('down')">
          <span class="mg-btn-icon">📉</span> BEAR — DOWN
        </button>
      </div>

      <div class="mg-keyboard-hint">
        <span class="mg-key">↑</span> / <span class="mg-key">U</span> = Bull &nbsp;·&nbsp;
        <span class="mg-key">↓</span> / <span class="mg-key">D</span> = Bear &nbsp;·&nbsp;
        <span class="mg-key">Space</span> = Next
      </div>

      <div class="mg-round-dots" id="mg-dots"></div>

      <!-- Result overlay lives inside the card -->
      <div class="mg-result" id="mg-result"></div>
      <!-- Streak badge -->
      <div class="mg-streak-badge ${streak >= 2 ? 'show' : ''}" id="mg-streak-badge">
        🔥 ${streak}× Streak
      </div>
      <!-- Multiplier flash -->
      <div class="mg-multiplier-flash" id="mg-mult-flash"></div>
    `;

    // Cache refs
    resultEl    = document.getElementById('mg-result');
    streakBadge = document.getElementById('mg-streak-badge');
    multFlash   = document.getElementById('mg-mult-flash');
    timerFillEl = document.getElementById('mg-timer-fill');

    _renderDots();
    _drawSparkline(s);
  }

  function _statHTML(label, val, cls) {
    return `<div class="mg-stat"><div class="mg-stat-label">${label}</div><div class="mg-stat-val ${cls}">${val}</div></div>`;
  }

  function _52wStr(s) {
    if (s.low52w != null && s.high52w != null) {
      return `$${_fmt(s.low52w)} / $${_fmt(s.high52w)}`;
    }
    return '—';
  }

  function _fmt(n) {
    if (n == null) return '—';
    return n >= 1000 ? n.toLocaleString('en-US', { maximumFractionDigits: 0 })
                     : n.toFixed(2);
  }

  function _renderDots() {
    const wrap = document.getElementById('mg-dots');
    if (!wrap) return;
    wrap.innerHTML = Array.from({ length: TOTAL_ROUNDS }, (_, i) => {
      let cls = '';
      if (i < roundIdx) {
        const h = history[i];
        cls = h ? `done-${h.outcome}` : 'done-timeout';
      } else if (i === roundIdx) {
        cls = 'current';
      }
      return `<div class="mg-dot ${cls}"></div>`;
    }).join('');
  }

  // ── Sparkline drawing ─────────────────────────────────────────────────────
  function _drawSparkline(s) {
    const canvas = document.getElementById('mg-spark');
    if (!canvas) return;

    // Try to use spark data from the main app's stockData array
    const match  = (window.stockData || []).find(x => x.ticker === s.ticker);
    const prices = match?.spark ?? s.spark ?? [];

    const dpr  = window.devicePixelRatio || 1;
    const W    = canvas.offsetWidth  || 460;
    const H    = canvas.offsetHeight || 80;
    canvas.width  = W * dpr;
    canvas.height = H * dpr;

    const ctx = canvas.getContext('2d');
    ctx.scale(dpr, dpr);

    if (!prices || prices.length < 2) {
      ctx.fillStyle = getComputedStyle(document.documentElement).getPropertyValue('--muted') || '#8b949e';
      ctx.font      = '12px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('No chart data', W / 2, H / 2);
      return;
    }

    const min   = Math.min(...prices);
    const max   = Math.max(...prices);
    const range = max - min || 1;
    const pad   = 6;

    const xStep = (W - pad * 2) / (prices.length - 1);
    const yOf   = v => pad + (1 - (v - min) / range) * (H - pad * 2);

    // Gradient fill
    const isUp = prices[prices.length - 1] >= prices[0];
    const grad = ctx.createLinearGradient(0, 0, 0, H);
    if (isUp) {
      grad.addColorStop(0, 'rgba(63,185,80,.30)');
      grad.addColorStop(1, 'rgba(63,185,80,.00)');
    } else {
      grad.addColorStop(0, 'rgba(248,81,73,.30)');
      grad.addColorStop(1, 'rgba(248,81,73,.00)');
    }

    ctx.beginPath();
    prices.forEach((p, i) => {
      const x = pad + i * xStep;
      const y = yOf(p);
      i === 0 ? ctx.moveTo(x, y) : ctx.lineTo(x, y);
    });
    // Close path for fill
    ctx.lineTo(pad + (prices.length - 1) * xStep, H);
    ctx.lineTo(pad, H);
    ctx.closePath();
    ctx.fillStyle = grad;
    ctx.fill();

    // Line
    ctx.beginPath();
    prices.forEach((p, i) => {
      const x = pad + i * xStep;
      const y = yOf(p);
      i === 0 ? ctx.moveTo(x, y) : ctx.lineTo(x, y);
    });
    ctx.strokeStyle = isUp ? '#3fb950' : '#f85149';
    ctx.lineWidth   = 1.8;
    ctx.lineJoin    = 'round';
    ctx.stroke();

    // Endpoint dot
    const lx = pad + (prices.length - 1) * xStep;
    const ly = yOf(prices[prices.length - 1]);
    ctx.beginPath();
    ctx.arc(lx, ly, 3.5, 0, Math.PI * 2);
    ctx.fillStyle = isUp ? '#3fb950' : '#f85149';
    ctx.fill();
  }

  // ── Timer ─────────────────────────────────────────────────────────────────
  function _startTimer(stock) {
    _stopTimer();
    timerStart = performance.now();

    function tick() {
      if (!timerFillEl) return;
      const elapsed = (performance.now() - timerStart) / 1000;
      const pct     = Math.max(0, 1 - elapsed / TIMER_SECS) * 100;
      timerFillEl.style.width = pct + '%';
      if (pct <= 25) timerFillEl.classList.add('urgent');
      if (elapsed >= TIMER_SECS) {
        _timeout(stock);
      } else {
        timerRAF = requestAnimationFrame(tick);
      }
    }
    timerRAF = requestAnimationFrame(tick);
  }

  function _stopTimer() {
    if (timerRAF) { cancelAnimationFrame(timerRAF); timerRAF = null; }
    if (timerID)  { clearTimeout(timerID); timerID = null; }
  }

  // ── Guess logic ───────────────────────────────────────────────────────────
  // Exposed on window so the inline onclick can reach it
  window._mgGuess = function (dir) { _guess(dir); };

  function _guess(dir) {
    if (guessed) return;
    guessed = true;
    _stopTimer();

    const stock   = pool[roundIdx];
    const actual  = _actualDirection(stock);
    const correct = dir === actual;
    const elapsed = (performance.now() - timerStart) / 1000;
    const mult    = _multiplier();

    let pts = 0;
    if (correct) {
      pts = BASE_POINTS * mult + (elapsed < 3 ? SPEED_BONUS : 0);
      score += pts;
      streak++;
    } else {
      streak = 0;
    }

    const outcome = correct ? 'correct' : 'wrong';
    history.push({ ticker: stock.ticker, guess: dir, actual, pts, outcome });

    _showResult(correct, stock, pts, dir, actual);
    _updateHeaderScore();
    _updateStreakBadge();
    if (correct && mult > 1) _flashMultiplier(mult);

    // Auto-advance after 2s
    timerID = setTimeout(_nextRound, 2200);
  }

  function _timeout(stock) {
    if (guessed) return;
    guessed = true;
    _stopTimer();
    streak  = 0;
    history.push({ ticker: stock.ticker, guess: null, actual: _actualDirection(stock), pts: 0, outcome: 'timeout' });
    _showResultTimeout(stock);
    _updateHeaderScore();
    _updateStreakBadge();
    timerID = setTimeout(_nextRound, 2200);
  }

  function _nextRound() {
    _stopTimer();
    roundIdx++;
    if (roundIdx >= TOTAL_ROUNDS) {
      _showGameOver();
    } else {
      _showRound();
    }
  }

  // Determine "correct" direction using today's change % (sign of change1d)
  // Positive = market thinks it's going up → UP is correct
  // Negative → DOWN is correct
  // Flat (0) → either is accepted (we treat UP as correct for simplicity)
  function _actualDirection(s) {
    const c = s.change1d ?? 0;
    return c >= 0 ? 'up' : 'down';
  }

  function _multiplier() {
    if (streak >= 5) return 4;
    if (streak >= 3) return 3;
    if (streak >= 2) return 2;
    return 1;
  }

  // ── Result screens ────────────────────────────────────────────────────────
  function _showResult(correct, stock, pts, dir, actual) {
    if (!resultEl) return;
    const icon     = correct ? '✅' : '❌';
    const title    = correct ? 'Correct!' : 'Wrong!';
    const dirLabel = (d) => d === 'up' ? '📈 UP' : '📉 DOWN';
    const sub      = correct
      ? `${stock.ticker} moved ${dirLabel(actual)} — you called it!`
      : `You guessed ${dirLabel(dir)}, but it went ${dirLabel(actual)}.`;

    const ptsStr = correct ? `+${pts} pts` : '0 pts';
    resultEl.className = `mg-result ${correct ? 'correct' : 'wrong'} visible`;
    resultEl.innerHTML = `
      <div class="mg-result-icon">${icon}</div>
      <div class="mg-result-title">${title}</div>
      <div class="mg-result-subtitle">${sub}</div>
      <div class="mg-result-pts">${ptsStr}</div>
      <div class="mg-result-next">Space / Enter to continue…</div>
    `;
    if (!correct) {
      card.classList.add('shake');
      card.addEventListener('animationend', () => card.classList.remove('shake'), { once: true });
    }
  }

  function _showResultTimeout(stock) {
    if (!resultEl) return;
    resultEl.className = 'mg-result timeout visible';
    resultEl.innerHTML = `
      <div class="mg-result-icon">⏰</div>
      <div class="mg-result-title">Time's up!</div>
      <div class="mg-result-subtitle">${stock.ticker} — you didn't decide in time.</div>
      <div class="mg-result-pts">0 pts</div>
      <div class="mg-result-next">Space / Enter to continue…</div>
    `;
  }

  function _updateHeaderScore() {
    // Re-render just the score number in the header
    const el = card.querySelector('.mg-meta');
    if (!el) return;
    const vals = el.querySelectorAll('.mg-meta-val');
    if (vals[1]) vals[1].textContent = score;
  }

  function _updateStreakBadge() {
    if (!streakBadge) return;
    if (streak >= 2) {
      streakBadge.textContent = `🔥 ${streak}× Streak`;
      streakBadge.classList.add('show');
    } else {
      streakBadge.classList.remove('show');
    }
  }

  function _flashMultiplier(mult) {
    if (!multFlash) return;
    multFlash.textContent = `${mult}×`;
    multFlash.classList.remove('animate');
    // Force reflow
    void multFlash.offsetWidth;
    multFlash.classList.add('animate');
    multFlash.addEventListener('animationend', () => {
      multFlash.classList.remove('animate');
    }, { once: true });
  }

  // ── Loading state ─────────────────────────────────────────────────────────
  function _showLoading(msg) {
    card.innerHTML = `
      <div class="mg-header">
        <div class="mg-title"><span class="mg-title-icon">🐂🐻</span> Bull or Bear?</div>
        <button class="mg-close" onclick="document.getElementById('mg-overlay').classList.remove('open')">✕</button>
      </div>
      <div class="mg-loading">
        <div class="spinner"></div>
        <p>${msg}</p>
      </div>
    `;
  }

  // ── Game over ─────────────────────────────────────────────────────────────
  function _showGameOver() {
    const correct  = history.filter(h => h.outcome === 'correct').length;
    const pct      = Math.round((correct / TOTAL_ROUNDS) * 100);
    const prevBest = parseInt(localStorage.getItem(LS_HIGHSCORE) || '0', 10);
    const newBest  = score > prevBest;
    if (newBest) localStorage.setItem(LS_HIGHSCORE, String(score));
    const hiScore  = newBest ? score : prevBest;

    const emoji = pct >= 80 ? '🏆' : pct >= 60 ? '📈' : pct >= 40 ? '🤔' : '📉';
    const title = pct >= 80 ? 'Market Genius!' : pct >= 60 ? 'Solid Trader' : pct >= 40 ? 'Not Bad' : 'Rough Session';
    const sub   = `${correct}/${TOTAL_ROUNDS} correct · ${pct}% accuracy`;

    const rows = history.map((h, i) => {
      const dirIcon = h.actual === 'up' ? '📈' : '📉';
      const gIcon   = h.guess  === 'up' ? '📈' : h.guess === 'down' ? '📉' : '—';
      return `
        <tr class="${h.outcome}">
          <td class="ticker-cell">${h.ticker}</td>
          <td>${gIcon} ${h.guess ?? 'timeout'}</td>
          <td>${dirIcon} ${h.actual}</td>
          <td class="pts-cell">${h.pts > 0 ? '+' + h.pts : 0}</td>
        </tr>`;
    }).join('');

    card.innerHTML = `
      <div class="mg-header">
        <div class="mg-title"><span class="mg-title-icon">🐂🐻</span> Bull or Bear?</div>
        <button class="mg-close" onclick="document.getElementById('mg-overlay').classList.remove('open')">✕</button>
      </div>
      <div class="mg-gameover">
        <div class="mg-gameover-emoji">${emoji}</div>
        <div class="mg-gameover-title">${title}</div>
        <div class="mg-gameover-subtitle">${sub}</div>
        ${newBest ? '<div class="mg-highscore-badge">🏅 New High Score!</div>' : ''}
        <div class="mg-score-display">
          <div class="mg-score-block">
            <div class="mg-score-block-label">Score</div>
            <div class="mg-score-block-val">${score}</div>
          </div>
          <div class="mg-score-block">
            <div class="mg-score-block-label">Best</div>
            <div class="mg-score-block-val gold">${hiScore}</div>
          </div>
          <div class="mg-score-block">
            <div class="mg-score-block-label">Accuracy</div>
            <div class="mg-score-block-val green">${pct}%</div>
          </div>
        </div>
        <div class="mg-scoreboard">
          <table>
            <thead><tr>
              <th>Ticker</th><th>Your Guess</th><th>Actual</th><th>Pts</th>
            </tr></thead>
            <tbody>${rows}</tbody>
          </table>
        </div>
        <div class="mg-gameover-actions">
          <button class="mg-btn-play-again" onclick="window.openMinigame()">▶ Play Again</button>
          <button class="mg-btn-close-gameover" onclick="document.getElementById('mg-overlay').classList.remove('open')">✕ Close</button>
        </div>
      </div>
    `;
  }

  // ── DOM bootstrap ─────────────────────────────────────────────────────────
  function _ensureDOM() {
    if (document.getElementById('mg-overlay')) {
      overlay = document.getElementById('mg-overlay');
      card    = overlay.querySelector('.mg-card');
      return;
    }

    overlay = document.createElement('div');
    overlay.id = 'mg-overlay';

    card = document.createElement('div');
    card.className = 'mg-card';

    overlay.appendChild(card);
    document.body.appendChild(overlay);

    // Close on backdrop click
    overlay.addEventListener('click', e => {
      if (e.target === overlay) _closeGame();
    });
  }

})();

/* ── Bull or Bear? Minigame ──────────────────────────────────────────────── */
/* Standalone IIFE — exposes only openMinigame() globally                    */

(function () {
  'use strict';

  // ── Constants ─────────────────────────────────────────────────────────────
  const API          = 'http://127.0.0.1:5000/api';
  const TOTAL_ROUNDS = 10;
  const TIMER_SECS   = 9;
  const BASE_POINTS  = 100;
  const SPEED_BONUS  = 30;
  const LS_HIGHSCORE = 'mg_highscore';
  const SECTORS      = ['all','Technology','Healthcare','Financials',
                        'Consumer','Energy','Industrials'];

  // ── State ─────────────────────────────────────────────────────────────────
  let pool    = [];
  let roundIdx, score, streak, history;
  let timerID = null, timerRAF = null, timerStart = 0;
  let guessed = false;
  let resultEl, streakBadge, multFlash, timerFillEl;
  let overlay, card;

  // ── Public entry point ────────────────────────────────────────────────────
  window.openMinigame = async function () {
    _ensureDOM();
    overlay.classList.add('open');
    document.addEventListener('keydown', _onKey);
    await _startGame();
  };

  function _closeGame() {
    overlay.classList.remove('open');
    document.removeEventListener('keydown', _onKey);
    _stopTimer();
  }

  // ── Keyboard ──────────────────────────────────────────────────────────────
  function _onKey(e) {
    if (!overlay.classList.contains('open')) return;
    if (e.key === 'Escape') { _closeGame(); return; }
    if (!guessed) {
      if (e.key === 'ArrowUp'   || e.key === 'u' || e.key === 'U') _guess('up');
      if (e.key === 'ArrowDown' || e.key === 'd' || e.key === 'D') _guess('down');
    } else {
      if (e.key === ' ' || e.key === 'Enter') _nextRound();
    }
  }

  // ── Game lifecycle ────────────────────────────────────────────────────────
  async function _startGame() {
    pool = []; roundIdx = 0; score = 0; streak = 0; history = [];
    _showLoading('Fetching live stocks…');
    try {
      pool = await _fetchPool();
    } catch (err) {
      _showLoading(`⚠️ Could not load stocks: ${err.message}`);
      return;
    }
    if (pool.length < TOTAL_ROUNDS) {
      _showLoading(`⚠️ Only ${pool.length} stocks available — need ${TOTAL_ROUNDS}.`);
      return;
    }
    _showRound();
  }

  async function _fetchPool() {
    const sA = SECTORS[Math.floor(Math.random() * SECTORS.length)];
    const sB = SECTORS[Math.floor(Math.random() * SECTORS.length)];
    const [a, b] = await Promise.all([
      fetch(`${API}/top-stocks?sector=${encodeURIComponent(sA)}&mode=random`).then(r => r.json()),
      fetch(`${API}/top-stocks?sector=${encodeURIComponent(sB)}&mode=momentum`).then(r => r.json()),
    ]);
    const combined = [...(a.stocks || []), ...(b.stocks || [])];
    const seen = new Set();
    const unique = combined.filter(s => { if (seen.has(s.ticker)) return false; seen.add(s.ticker); return true; });
    for (let i = unique.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [unique[i], unique[j]] = [unique[j], unique[i]];
    }
    return unique;
  }

  function _showRound() {
    guessed = false;
    const stock = pool[roundIdx];
    _renderRound(stock);
    _startTimer(stock);
  }

// ── Render a round ────────────────────────────────────────────────────────
function _renderRound(s) {
  const change = s.change1d ?? 0;
  const chgCls = change > 0 ? 'up' : change < 0 ? 'down' : 'flat';
  const chgStr = (change > 0 ? '+' : '') + change.toFixed(2) + '%';
  const rsi    = s.rsi   ?? null;
  const pe     = s.pe    ?? null;
  const sc     = s.score ?? null;
  const aiCls  = sc >= 65 ? 'up' : sc >= 40 ? '' : 'down';
  const rsiCls = rsi > 70 ? 'down' : rsi < 35 ? 'up' : 'warn';
  const mult   = _multiplier();

  card.innerHTML = `
    <div class="mg-header">
      <div class="mg-title"><span class="mg-title-icon">🐂🐻</span> Bull or Bear?</div>
      <div class="mg-meta">
        <span>Round <span class="mg-meta-val">${roundIdx + 1}/${TOTAL_ROUNDS}</span></span>
        <span>Score <span class="mg-meta-val" id="mg-score-val">${score}</span></span>
        ${mult > 1 ? `<span style="color:var(--gold);font-weight:800;">${mult}× STREAK</span>` : ''}
      </div>
      <button class="mg-close" id="mg-close-btn">✕</button>
    </div>

    <div class="mg-timer-track">
      <div class="mg-timer-fill" id="mg-timer-fill"></div>
    </div>

    <div class="mg-body">
      <div class="mg-stock-hero">
        <div class="mg-stock-left">
          <div class="mg-ticker">${s.ticker}</div>
          <div class="mg-name">${s.name || ''}</div>
          <div class="mg-sector-chip">${s.sector || 'Market'}</div>
        </div>
        <div class="mg-price-block">
          <div class="mg-price">$${_fmt(s.price)}</div>
          <div class="mg-day-change ${chgCls}">${chgStr} today</div>
        </div>
      </div>

      <div class="mg-spark-wrap">
        <canvas id="mg-spark"></canvas>
        <span class="mg-spark-label">30-day</span>
      </div>

      <div class="mg-stats">
        ${_statHTML('AI Score', sc !== null ? sc.toFixed(0) : '—', aiCls)}
        ${_statHTML('RSI', rsi !== null ? rsi.toFixed(0) : '—', rsiCls)}
        ${_statHTML('P/E', pe !== null ? pe.toFixed(1) : '—', pe > 50 ? 'down' : pe < 15 ? 'up' : '')}
        ${_statHTML('52w Range', _52wStr(s), '')}
      </div>

      <div class="mg-cta">Will <strong>${s.ticker}</strong> be <strong>higher or lower</strong> next week?</div>
    </div>

    <div class="mg-actions">
      <button class="mg-btn mg-btn-bull" id="mg-bull-btn">
        <span class="mg-btn-icon">📈</span> BULL — UP
      </button>
      <button class="mg-btn mg-btn-bear" id="mg-bear-btn">
        <span class="mg-btn-icon">📉</span> BEAR — DOWN
      </button>
    </div>

    <div class="mg-keyboard-hint">
      <span class="mg-key">↑</span>/<span class="mg-key">U</span> = Bull &nbsp;·&nbsp;
      <span class="mg-key">↓</span>/<span class="mg-key">D</span> = Bear &nbsp;·&nbsp;
      <span class="mg-key">Space</span> = Next
    </div>

    <div class="mg-round-dots" id="mg-dots"></div>

    <div class="mg-result" id="mg-result"></div>
    <div class="mg-streak-badge ${streak >= 2 ? 'show' : ''}" id="mg-streak-badge">
      🔥 ${streak}× Streak
    </div>
    <div class="mg-multiplier-flash" id="mg-mult-flash"></div>
  `;

  // Wire up buttons
  document.getElementById('mg-close-btn').addEventListener('click', _closeGame);
  document.getElementById('mg-bull-btn').addEventListener('click', () => _guess('up'));
  document.getElementById('mg-bear-btn').addEventListener('click', () => _guess('down'));

  // Cache element refs
  resultEl    = document.getElementById('mg-result');
  streakBadge = document.getElementById('mg-streak-badge');
  multFlash   = document.getElementById('mg-mult-flash');
  timerFillEl = document.getElementById('mg-timer-fill');

  _renderDots();
  _drawSparkline(s);
}

function _statHTML(label, val, cls) {
  return `<div class="mg-stat"><div class="mg-stat-label">${label}</div><div class="mg-stat-val ${cls}">${val}</div></div>`;
}
function _52wStr(s) {
  return (s.low52w != null && s.high52w != null) ? `$${_fmt(s.low52w)}/$${_fmt(s.high52w)}` : '—';
}
function _fmt(n) {
  if (n == null) return '—';
  return n >= 1000 ? n.toLocaleString('en-US', { maximumFractionDigits: 0 }) : n.toFixed(2);
}

function _renderDots() {
  const wrap = document.getElementById('mg-dots');
  if (!wrap) return;
  wrap.innerHTML = Array.from({ length: TOTAL_ROUNDS }, (_, i) => {
    let cls = '';
    if (i < roundIdx) { const h = history[i]; cls = h ? `done-${h.outcome}` : 'done-timeout'; }
    else if (i === roundIdx) cls = 'current';
    return `<div class="mg-dot ${cls}"></div>`;
  }).join('');
}

