// ── Timer ─────────────────────────────────────────────────────────────────
function _startTimer(stock) {
  _stopTimer();
  timerStart = performance.now();
  function tick() {
    if (!timerFillEl) return;
    const elapsed = (performance.now() - timerStart) / 1000;
    const pct = Math.max(0, 1 - elapsed / TIMER_SECS) * 100;
    timerFillEl.style.width = pct + '%';
    if (pct <= 25) timerFillEl.classList.add('urgent');
    if (elapsed >= TIMER_SECS) { _timeout(stock); }
    else { timerRAF = requestAnimationFrame(tick); }
  }
  timerRAF = requestAnimationFrame(tick);
}

function _stopTimer() {
  if (timerRAF) { cancelAnimationFrame(timerRAF); timerRAF = null; }
  if (timerID)  { clearTimeout(timerID); timerID = null; }
}

// ── Guess logic ───────────────────────────────────────────────────────────
function _guess(dir) {
  if (guessed) return;
  guessed = true;
  _stopTimer();
  const stock   = pool[roundIdx];
  const actual  = _actualDir(stock);
  const correct = dir === actual;
  const elapsed = (performance.now() - timerStart) / 1000;
  const mult    = _multiplier();
  let pts = 0;
  if (correct) {
    pts = BASE_POINTS * mult + (elapsed < 3 ? SPEED_BONUS : 0);
    score += pts;
    streak++;
  } else {
    streak = 0;
  }
  const outcome = correct ? 'correct' : 'wrong';
  history.push({ ticker: stock.ticker, guess: dir, actual, pts, outcome });
  _showResult(correct, stock, pts, dir, actual);
  _updateHeaderScore();
  _updateStreakBadge();
  if (correct && mult > 1) _flashMultiplier(mult);
  timerID = setTimeout(_nextRound, 2200);
}

function _timeout(stock) {
  if (guessed) return;
  guessed = true;
  _stopTimer();
  streak = 0;
  history.push({ ticker: stock.ticker, guess: null, actual: _actualDir(stock), pts: 0, outcome: 'timeout' });
  if (resultEl) {
    resultEl.className = 'mg-result timeout visible';
    resultEl.innerHTML = `
      <div class="mg-result-icon">⏰</div>
      <div class="mg-result-title">Time's up!</div>
      <div class="mg-result-subtitle">${stock.ticker} — you didn't decide in time.</div>
      <div class="mg-result-pts">0 pts</div>
      <div class="mg-result-next">Space / Enter to continue…</div>`;
  }
  _updateHeaderScore();
  _updateStreakBadge();
  timerID = setTimeout(_nextRound, 2200);
}

function _nextRound() {
  _stopTimer();
  roundIdx++;
  if (roundIdx >= TOTAL_ROUNDS) _showGameOver();
  else _showRound();
}

function _actualDir(s) { return (s.change1d ?? 0) >= 0 ? 'up' : 'down'; }
function _multiplier() {
  if (streak >= 5) return 4;
  if (streak >= 3) return 3;
  if (streak >= 2) return 2;
  return 1;
}

// ── Result overlay ────────────────────────────────────────────────────────
function _showResult(correct, stock, pts, dir, actual) {
  if (!resultEl) return;
  const dL  = d => d === 'up' ? '📈 UP' : '📉 DOWN';
  const sub = correct
    ? `${stock.ticker} moved ${dL(actual)} — you nailed it!`
    : `You guessed ${dL(dir)}, but it went ${dL(actual)}.`;
