input.new_text:
/* ── Name That Stock! — Minigame styles ─────────────────────────────────── */
/* Inherits all CSS custom-property tokens from the main app                 */

/* ── Toolbar trigger button ── */
.btn-minigame {
  background: linear-gradient(135deg, #a371f7 0%, #58a6ff 100%);
  color: #fff;
  position: relative;
  overflow: hidden;
}
.btn-minigame::after {
  content: '';
  position: absolute;
  inset: 0;
  background: rgba(255,255,255,0);
  transition: background .15s;
}
.btn-minigame:hover::after { background: rgba(255,255,255,.12); }

/* ── Backdrop overlay ── */
#mg-overlay {
  position: fixed;
  inset: 0;
  z-index: 9000;
  background: rgba(0,0,0,.82);
  backdrop-filter: blur(6px);
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  pointer-events: none;
  transition: opacity .25s;
}
#mg-overlay.open {
  opacity: 1;
  pointer-events: all;
}

/* ── Game card ── */
.mg-card {
  background: var(--bg2);
  border: 1px solid var(--border);
  border-radius: 16px;
  box-shadow: 0 24px 80px rgba(0,0,0,.7);
  width: min(560px, 96vw);
  max-height: 92vh;
  overflow-y: auto;
  overflow-x: hidden;
  display: flex;
  flex-direction: column;
  position: relative;
}

/* ── Header ── */
.mg-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 20px 12px;
  border-bottom: 1px solid var(--border);
  background: var(--bg3);
  position: sticky;
  top: 0;
  z-index: 2;
}
.mg-title {
  font-size: 1rem;
  font-weight: 800;
  display: flex;
  align-items: center;
  gap: 8px;
}
.mg-title-icon { font-size: 1.2rem; }
.mg-meta {
  display: flex;
  align-items: center;
  gap: 14px;
  font-size: .78rem;
  color: var(--muted);
}
.mg-meta-val { font-weight: 700; color: var(--text); }
.mg-close {
  background: none;
  border: none;
  color: var(--muted);
  font-size: 1.1rem;
  cursor: pointer;
  padding: 2px 6px;
  border-radius: 4px;
  transition: background .15s, color .15s;
  line-height: 1;
}
.mg-close:hover { background: var(--bg); color: var(--text); }

/* ── Body ── */
.mg-body { padding: 20px 24px 8px; }

/* ── Round intro ── */
.mg-round-intro {
  text-align: center;
  font-size: .72rem;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: .07em;
  margin-bottom: 16px;
  font-weight: 600;
}

/* ── Points banner ── */
.mg-points-available {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  margin-bottom: 16px;
}
.mg-pts-label { font-size: .72rem; color: var(--muted); }
.mg-pts-value {
  font-size: 1.4rem;
  font-weight: 900;
  color: var(--gold);
  transition: color .3s, font-size .2s;
  line-height: 1;
}
.mg-pts-value.decayed { color: var(--accent); }
.mg-pts-value.low     { color: var(--muted); }

/* ── Clues list ── */
.mg-clues {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin-bottom: 18px;
}

.mg-clue {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  background: var(--bg3);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 10px 14px;
  animation: mg-clue-in .3s cubic-bezier(0.34,1.56,0.64,1);
}
.mg-clue-num {
  flex-shrink: 0;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  background: var(--accent);
  color: #fff;
  font-size: .65rem;
  font-weight: 800;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-top: 1px;
}
.mg-clue-body { flex: 1; min-width: 0; }
.mg-clue-label {
  font-size: .62rem;
  text-transform: uppercase;
  letter-spacing: .06em;
  color: var(--muted);
  margin-bottom: 2px;
  font-weight: 600;
}
.mg-clue-text {
  font-size: .9rem;
  font-weight: 600;
  color: var(--text);
  line-height: 1.35;
}
.mg-clue-text .hi { color: var(--accent); }
.mg-clue-text .up { color: var(--green); }
.mg-clue-text .dn { color: var(--red); }
.mg-clue-text .warn { color: var(--gold); }

/* ── Sparkline clue ── */
.mg-clue-spark {
  width: 100%;
  height: 50px;
  display: block;
  margin-top: 4px;
  border-radius: 4px;
}

/* ── Reveal button ── */
.mg-reveal-btn {
  width: 100%;
  height: 40px;
  border: 1px dashed var(--border);
  border-radius: 10px;
  background: transparent;
  color: var(--muted);
  font-size: .82rem;
  font-weight: 600;
  cursor: pointer;
  transition: border-color .15s, color .15s, background .15s, transform .15s cubic-bezier(0.34,1.56,0.64,1);
  margin-bottom: 16px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
}
.mg-reveal-btn:hover {
  border-color: var(--accent);
  color: var(--accent);
  background: rgba(88,166,255,.06);
  transform: translateY(-1px);
}
.mg-reveal-btn:disabled {
  opacity: .35;
  cursor: default;
  transform: none;
}

/* ── Multiple choice options ── */
.mg-choices {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
  margin-bottom: 14px;
}
.mg-choice-btn {
  height: 46px;
  border: 1px solid var(--border);
  border-radius: 10px;
  background: var(--bg3);
  color: var(--text);
  font-size: .9rem;
  font-weight: 700;
  cursor: pointer;
