/* ── Free-text ticker input ── */
.mg-input-row { display: flex; gap: 8px; margin-bottom: 8px; }
.mg-ticker-input {
  flex: 1; height: 40px; background: var(--bg3);
  border: 1px solid var(--border); border-radius: 8px;
  color: var(--text); font-size: .95rem; font-weight: 700;
  padding: 0 12px; text-transform: uppercase; letter-spacing: .05em;
  transition: border-color .15s, box-shadow .15s;
}
.mg-ticker-input:focus { outline: none; border-color: var(--accent); box-shadow: 0 0 0 2px rgba(88,166,255,.15); }
.mg-ticker-input.shake { animation: mg-shake .3s ease; }
.mg-submit-btn {
  height: 40px; padding: 0 18px; background: var(--accent);
  color: #fff; border: none; border-radius: 8px;
  font-size: .85rem; font-weight: 700; cursor: pointer;
  transition: transform .15s cubic-bezier(0.34,1.56,0.64,1), box-shadow .15s, opacity .15s;
}
.mg-submit-btn:hover { transform: translateY(-2px) scale(1.04); box-shadow: 0 4px 14px rgba(88,166,255,.3); }
.mg-submit-btn:active { transform: scale(.96); }
.mg-submit-btn:disabled { opacity: .4; cursor: default; transform: none; }
.mg-mode-hint { text-align: center; font-size: .65rem; color: var(--muted); margin-bottom: 14px; }
.mg-mode-hint span { color: var(--accent); cursor: pointer; text-decoration: underline dotted; }

/* ── Post-guess answer reveal ── */
.mg-answer-reveal {
  border-radius: 10px; padding: 14px 16px; margin-bottom: 14px;
  text-align: center; animation: mg-pop .3s cubic-bezier(0.34,1.56,0.64,1);
}
.mg-answer-reveal.correct { background: rgba(63,185,80,.14); border: 1px solid rgba(63,185,80,.3); }
.mg-answer-reveal.wrong   { background: rgba(248,81,73,.12); border: 1px solid rgba(248,81,73,.25); }
.mg-answer-reveal.skip    { background: rgba(139,148,158,.1); border: 1px solid var(--border); }
.mg-answer-icon   { font-size: 2rem; }
.mg-answer-result { font-size: 1rem; font-weight: 800; margin: 4px 0 2px; }
.mg-answer-reveal.correct .mg-answer-result { color: var(--green); }
.mg-answer-reveal.wrong   .mg-answer-result { color: var(--red); }
.mg-answer-reveal.skip    .mg-answer-result { color: var(--muted); }
.mg-answer-sub    { font-size: .78rem; color: var(--muted); }
.mg-answer-ticker { color: var(--accent); font-weight: 800; }
.mg-answer-pts    { font-size: 1.1rem; font-weight: 900; color: var(--gold); margin-top: 6px; }

/* ── Navigation buttons ── */
.mg-next-btn {
  width: 100%; height: 44px; background: var(--bg3);
  border: 1px solid var(--border); border-radius: 10px;
  color: var(--text); font-size: .88rem; font-weight: 700; cursor: pointer;
  transition: border-color .15s, transform .15s cubic-bezier(0.34,1.56,0.64,1), box-shadow .15s;
  margin-bottom: 6px; display: flex; align-items: center; justify-content: center; gap: 8px;
}
.mg-next-btn:hover { border-color: var(--accent); transform: translateY(-2px); box-shadow: 0 4px 14px rgba(88,166,255,.12); }
.mg-skip-btn {
  width: 100%; height: 34px; background: transparent; border: none;
  color: var(--muted); font-size: .75rem; font-weight: 600; cursor: pointer;
  transition: color .15s; margin-bottom: 10px;
}
.mg-skip-btn:hover { color: var(--text); }

/* ── Round progress dots ── */
.mg-round-dots { display: flex; gap: 5px; justify-content: center; padding: 6px 0 16px; }
.mg-dot { width: 8px; height: 8px; border-radius: 50%; background: var(--border); transition: background .2s, transform .2s; }
.mg-dot.done-correct { background: var(--green); }
.mg-dot.done-wrong   { background: var(--red); }
.mg-dot.done-skip    { background: var(--muted); }
.mg-dot.current      { background: var(--accent); transform: scale(1.3); }

/* ── Streak badge ── */
.mg-streak-badge {
  position: absolute; top: 56px; right: 16px;
  background: var(--gold); color: #0d1117;
  border-radius: 20px; font-size: .7rem; font-weight: 800;
  padding: 3px 10px; display: none; z-index: 5;
  animation: mg-pop .3s cubic-bezier(0.34,1.56,0.64,1);
}
.mg-streak-badge.show { display: block; }

/* ── Multiplier flash ── */
.mg-multiplier-flash {
  position: absolute; top: 40%; left: 50%;
  transform: translate(-50%,-50%) scale(.5);
  font-size: 2.2rem; font-weight: 900; color: var(--gold);
  pointer-events: none; opacity: 0;
  text-shadow: 0 0 20px rgba(210,153,34,.6); z-index: 20;
}
.mg-multiplier-flash.animate { animation: mg-multi-pop .6s cubic-bezier(0.34,1.56,0.64,1) forwards; }

/* ── Loading ── */
.mg-loading { padding: 52px 24px; text-align: center; color: var(--muted); font-size: .9rem; }
.mg-loading .spinner {
  width: 28px; height: 28px; border: 3px solid var(--border);
  border-top-color: var(--accent); border-radius: 50%;
  animation: spin .7s linear infinite; margin: 0 auto 14px;
}

/* ── Game over ── */
.mg-gameover { padding: 28px 24px 24px; text-align: center; }
.mg-gameover-emoji    { font-size: 3rem; margin-bottom: 8px; }
.mg-gameover-title    { font-size: 1.4rem; font-weight: 900; margin-bottom: 4px; }
.mg-gameover-subtitle { font-size: .82rem; color: var(--muted); margin-bottom: 20px; }
.mg-score-display { display: flex; justify-content: center; gap: 20px; margin-bottom: 20px; flex-wrap: wrap; }
.mg-score-block { background: var(--bg3); border: 1px solid var(--border); border-radius: 10px; padding: 12px 18px; min-width: 86px; }
.mg-score-block-label { font-size: .62rem; text-transform: uppercase; letter-spacing: .06em; color: var(--muted); margin-bottom: 4px; }
.mg-score-block-val { font-size: 1.5rem; font-weight: 900; color: var(--accent); }
.mg-score-block-val.gold  { color: var(--gold); }
.mg-score-block-val.green { color: var(--green); }
.mg-scoreboard { width: 100%; max-height: 210px; overflow-y: auto; margin-bottom: 18px; }
.mg-scoreboard table { width: 100%; border-collapse: collapse; font-size: .78rem; }
.mg-scoreboard th { text-align: left; color: var(--muted); font-weight: 600; padding: 4px 8px; border-bottom: 1px solid var(--border); font-size: .66rem; text-transform: uppercase; letter-spacing: .05em; }
.mg-scoreboard td { padding: 5px 8px; border-bottom: 1px solid rgba(48,54,61,.5); }
.mg-scoreboard tr.correct td { color: var(--green); }
.mg-scoreboard tr.wrong   td { color: var(--red); }
.mg-scoreboard tr.skip    td { color: var(--muted); }
.mg-scoreboard .ticker-cell  { font-weight: 700; color: var(--accent); }
.mg-scoreboard .pts-cell     { font-weight: 700; text-align: right; }
.mg-scoreboard .clues-cell   { text-align: center; color: var(--muted); }
.mg-gameover-actions { display: flex; gap: 10px; justify-content: center; }
.mg-btn-play-again {
  background: linear-gradient(135deg, #a371f7, #58a6ff);
  color: #fff; border: none; border-radius: 8px;
  padding: 9px 24px; font-size: .88rem; font-weight: 700; cursor: pointer;
  transition: transform .15s cubic-bezier(0.34,1.56,0.64,1), box-shadow .15s;
}
.mg-btn-play-again:hover { transform: translateY(-2px) scale(1.04); box-shadow: 0 6px 20px rgba(163,113,247,.35); }
