@app.route("/api/minigame/hint")
def minigame_hint():
    """Return one recent news item for a ticker, with the ticker symbol
    scrubbed from the headline so it doesn't spoil the minigame answer."""
    ticker = request.args.get("ticker", "").strip().upper()
    if not ticker:
        return jsonify({"error": "ticker param required"}), 400

    try:
        stock  = yf.Ticker(ticker)
        news   = stock.news or []

        # yfinance ≥0.2.x wraps articles in a "content" sub-object;
        # older versions expose fields at the top level — handle both.
        def _normalise(item: dict) -> dict:
            c = item.get("content", item)
            title   = c.get("title", "")
            summary = c.get("summary", c.get("description", ""))
            url     = (c.get("canonicalUrl") or c.get("clickThroughUrl") or {}).get("url", "")
            source  = (c.get("provider") or {}).get("displayName", "")
            pub     = c.get("pubDate", c.get("providerPublishTime", ""))
            return {"title": title, "summary": summary, "url": url,
                    "source": source, "publishedAt": pub}

        articles = [_normalise(n) for n in news if n]
        # Filter to articles that have a title and a URL
        articles = [a for a in articles if a["title"] and a["url"]]

        if not articles:
            return jsonify({"error": "No news available for this ticker"}), 404

        # Scrub the ticker symbol (and common company-name fragments) from
        # title + summary so the answer is not given away outright.
        import re as _re
        def _scrub(text: str) -> str:
            # Remove bare ticker in parens like "(AAPL)" or "NASDAQ: AAPL"
            text = _re.sub(
                r'\b(NYSE|NASDAQ|AMEX)[\s:]+' + _re.escape(ticker) + r'\b',
                '[undisclosed]', text, flags=_re.IGNORECASE)
            text = _re.sub(
                r'\(' + _re.escape(ticker) + r'\)',
                '([?])', text, flags=_re.IGNORECASE)
            # Remove standalone all-caps ticker as a whole word
            text = _re.sub(
                r'\b' + _re.escape(ticker) + r'\b',
                '[?]', text)
            return text

        # Pick the first article that doesn't lead with the raw ticker symbol
        chosen = articles[0]
        for a in articles:
            if not a["title"].strip().upper().startswith(ticker):
                chosen = a
                break

        chosen["title"]   = _scrub(chosen["title"])
        chosen["summary"] = _scrub(chosen["summary"])[:280]  # cap summary length

        logger.info("minigame-hint: %s → %s", ticker, chosen["title"][:60])
        return jsonify(chosen)

    except Exception as exc:
        logger.warning("minigame-hint failed for %s: %s", ticker, exc)
        return jsonify({"error": str(exc)}), 500

