function scoreGuess(guess, target) {
  const result     = Array(guess.length).fill('absent');
  const targetLeft = target.split('');
  const guessLeft  = guess.split('');
  for (let i = 0; i < guess.length; i++) {
    if (i < target.length && guess[i] === target[i]) {
      result[i] = 'correct'; targetLeft[i] = null; guessLeft[i] = null;
    }
  }
  for (let i = 0; i < guess.length; i++) {
    if (guessLeft[i] === null) continue;
    const ti = targetLeft.indexOf(guessLeft[i]);
    if (ti !== -1) { result[i] = 'present'; targetLeft[ti] = null; }
  }
  return result;
}

const cases = [
  // exact match
  ['MSFT', 'MSFT', ['correct','correct','correct','correct']],
  // full miss
  ['TSLA', 'NVDA', ['absent','absent','absent','absent']],
  // first letter in wrong position (A is in AAPL but not pos 0 of AMZN)
  ['AMZN', 'AAPL', ['present','absent','absent','absent']],
  // different lengths — GOOGL vs AAPL
  ['GOOGL','AAPL',  ['absent','absent','absent','absent','absent']],
  // partial overlap — AAPL vs AMAT: A@0=correct, A@1=correct, P absent, L absent
  ['AAPL', 'AMAT', ['correct','correct','absent','absent']],
  // AMAT vs AAPL: A@0=correct, A@1=correct, A is present (1 remaining A in AAPL), T absent
  ['AMAT', 'AAPL', ['correct','correct','present','absent']],
  // duplicate letter consumed correctly: MARA vs MSFT — M correct, rest absent
  ['MARA', 'MSFT', ['correct','absent','absent','absent']],
  // COIN vs COST: C correct, O correct, I absent, N absent
  ['COIN', 'COST', ['correct','correct','absent','absent']],
  // single char ticker
  ['V',    'V',    ['correct']],
  ['V',    'A',    ['absent']],
];

let ok = true;
cases.forEach(([g, t, exp]) => {
  const got  = scoreGuess(g, t);
  const pass = JSON.stringify(got) === JSON.stringify(exp);
  const line = got.map((r, i) => g[i] + ':' + r[0]).join(' ');
  console.log((pass ? 'PASS' : 'FAIL'), g.padEnd(5), 'vs', t.padEnd(5), '->', line);
  if (!pass) { console.log('     expected:', exp); ok = false; }
});
console.log(ok ? '\nAll tests passed ✓' : '\nSome tests FAILED ✗');

