/* ── Mascot — Penny the Bull ── */
.mg-mascot {
  position: absolute;
  bottom: 18px;
  right: 24px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  z-index: 10;
  pointer-events: none;
  /* start hidden; shown once overlay is open */
  opacity: 0;
  transition: opacity .3s .15s;
}
#mg-overlay.open .mg-mascot { opacity: 1; }

.mg-mascot-face {
  font-size: 2.4rem;
  line-height: 1;
  filter: drop-shadow(0 2px 6px rgba(0,0,0,.5));
  transition: filter .2s;
}

/* Speech bubble — sits above the face */
.mg-mascot-bubble {
  position: relative;
  max-width: 180px;
  min-width: 100px;
  padding: 8px 11px;
  background: var(--bg3);
  border: 1px solid var(--border);
  border-radius: 12px;
  font-size: .72rem;
  line-height: 1.45;
  color: var(--text);
  text-align: center;
  box-shadow: 0 4px 16px rgba(0,0,0,.4);
  word-break: break-word;
}
/* Bubble tail — little triangle pointing down toward the face */
.mg-mascot-bubble::after {
  content: '';
  position: absolute;
  bottom: -7px;
  left: 50%;
  transform: translateX(-50%);
  border-left: 7px solid transparent;
  border-right: 7px solid transparent;
  border-top: 7px solid var(--border);
}
.mg-mascot-bubble::before {
  content: '';
  position: absolute;
  bottom: -6px;
  left: 50%;
  transform: translateX(-50%);
  border-left: 6px solid transparent;
  border-right: 6px solid transparent;
  border-top: 6px solid var(--bg3);
  z-index: 1;
}

/* Mood-tinted borders */
.mg-mascot[data-mood="correct"] .mg-mascot-bubble,
.mg-mascot[data-mood="streak"]  .mg-mascot-bubble {
  border-color: rgba(63,185,80,.5);
  background: rgba(63,185,80,.08);
  color: var(--green);
}
.mg-mascot[data-mood="correct"] .mg-mascot-bubble::after,
.mg-mascot[data-mood="streak"]  .mg-mascot-bubble::after  { border-top-color: rgba(63,185,80,.5); }
.mg-mascot[data-mood="correct"] .mg-mascot-bubble::before,
.mg-mascot[data-mood="streak"]  .mg-mascot-bubble::before { border-top-color: rgba(63,185,80,.08); }

.mg-mascot[data-mood="close"] .mg-mascot-bubble,
.mg-mascot[data-mood="warm"]  .mg-mascot-bubble {
  border-color: rgba(210,153,34,.45);
  background: rgba(210,153,34,.07);
  color: var(--gold);
}
.mg-mascot[data-mood="close"] .mg-mascot-bubble::after,
.mg-mascot[data-mood="warm"]  .mg-mascot-bubble::after  { border-top-color: rgba(210,153,34,.45); }
.mg-mascot[data-mood="close"] .mg-mascot-bubble::before,
.mg-mascot[data-mood="warm"]  .mg-mascot-bubble::before { border-top-color: rgba(210,153,34,.07); }

.mg-mascot[data-mood="cold"] .mg-mascot-bubble {
  border-color: rgba(88,166,255,.35);
  background: rgba(88,166,255,.06);
  color: var(--accent);
}
.mg-mascot[data-mood="cold"] .mg-mascot-bubble::after  { border-top-color: rgba(88,166,255,.35); }
.mg-mascot[data-mood="cold"] .mg-mascot-bubble::before { border-top-color: rgba(88,166,255,.06); }

.mg-mascot[data-mood="skip"] .mg-mascot-bubble {
  border-color: rgba(248,81,73,.35);
  background: rgba(248,81,73,.06);
  color: var(--red);
}
.mg-mascot[data-mood="skip"] .mg-mascot-bubble::after  { border-top-color: rgba(248,81,73,.35); }
.mg-mascot[data-mood="skip"] .mg-mascot-bubble::before { border-top-color: rgba(248,81,73,.06); }

.mg-mascot[data-mood="hint"] .mg-mascot-bubble {
  border-color: rgba(210,153,34,.45);
  background: rgba(210,153,34,.07);
}

/* Bounce animation */
@keyframes mg-mascot-bounce {
  0%   { transform: translateY(0)    scale(1); }
  25%  { transform: translateY(-10px) scale(1.06); }
  50%  { transform: translateY(-4px)  scale(.98); }
  70%  { transform: translateY(-7px)  scale(1.03); }
  100% { transform: translateY(0)    scale(1); }
}
.mg-mascot-bounce { animation: mg-mascot-bounce .55s cubic-bezier(.36,.07,.19,.97) both; }

/* ── Animations ── */

